#===============================================================================
# ProceduralEncounters - Settings
# Writes the wild encounters of a world generated by MapProceduralGenerator
# into PBS/encounters.txt: which Pokémon of the roster appear where, at which
# levels and how often, the same for a given world seed.
#===============================================================================
module ProceduralEncounters
  # The Pokémon of the game (types, Monotype types, strength tier, family).
  ROSTER_FILE = "docs/roster/liste-300.csv"
  # Evolutions (method and level) are read from these.
  POKEMON_PBS = "PBS/pokemon.txt"
  POKEMON_FORMS_PBS = "PBS/pokemon_forms.txt"
  ENCOUNTERS_PBS = "PBS/encounters.txt"

  # Tiles that trigger encounters in the Outside tileset (as stored by MapGen:
  # 384 + n for T<n>, 48 * slot for an autotile): tall grass T6 and very tall
  # grass T7, water A1 (deep water included).
  GRASS_TILES = [384 + 6, 384 + 7].freeze
  WATER_TILES = [48].freeze

  # Ground tile of a place (its ambiance) => land biome, « herbe » otherwise.
  GROUND_BIOMES = { 384 + 50 => "prairie", 384 + 162 => "sable", 384 + 106 => "terre" }.freeze

  # Biome => type => weight (0 or absent = never there). A Pokémon takes the
  # best weight among its own types.
  BIOMES = {
    "herbe"    => { NORMAL: 3, BUG: 3, GRASS: 3, FLYING: 3, POISON: 2, ELECTRIC: 2, FAIRY: 2,
                    GROUND: 1, FIGHTING: 1, DARK: 1, PSYCHIC: 1, FIRE: 1, DRAGON: 1 },
    "prairie"  => { NORMAL: 3, GRASS: 3, FAIRY: 3, BUG: 2, FLYING: 2, ELECTRIC: 2, FIRE: 2,
                    PSYCHIC: 1, GROUND: 1, DRAGON: 1 },
    "sable"    => { GROUND: 3, FIRE: 3, ROCK: 2, BUG: 2, POISON: 1, NORMAL: 1, FIGHTING: 1,
                    DRAGON: 1, STEEL: 1 },
    "terre"    => { FIGHTING: 3, GROUND: 2, ROCK: 2, NORMAL: 2, DARK: 2, FIRE: 2, STEEL: 1,
                    POISON: 1 },
    "foret"    => { BUG: 3, GRASS: 3, GHOST: 2, FAIRY: 2, POISON: 2, DARK: 2, PSYCHIC: 1,
                    NORMAL: 1, FLYING: 1 },
    "montagne" => { ROCK: 3, GROUND: 3, FIGHTING: 3, FLYING: 2, STEEL: 2, DRAGON: 2, ICE: 2,
                    FIRE: 1, NORMAL: 1 },
    "ville"    => { NORMAL: 3, POISON: 2, ELECTRIC: 2, STEEL: 2, PSYCHIC: 2, DARK: 2, FAIRY: 2,
                    GHOST: 1, FIGHTING: 1, FIRE: 1, GRASS: 1 },
    "grotte"   => { ROCK: 3, GROUND: 3, STEEL: 2, GHOST: 2, DARK: 2, POISON: 2, DRAGON: 2,
                    ICE: 1, FIGHTING: 1, PSYCHIC: 1 },
    "eau"      => { WATER: 3 }
  }.freeze
  # Excess of a place (« Demesure ») => land biome, over the ground's.
  EXCESS_BIOMES = { "forêt profonde" => "foret", "mer d'herbes" => "prairie", "chaos rocheux" => "montagne",
                    "montagne colossale" => "montagne", "ville-jardin" => "foret" }.freeze

  # Encounter types written: number of species drawn (range), and at most
  # once the coverage passes have added theirs (types, families), density (nil = none, as for the rods), level shift
  # from the place's levels, required type, coverage (a Monotype run counts on
  # it: land, caves, and surfing once Surf is obtained).
  TABLES = {
    "Land"     => { species: 4..7, max: 14, density: 21, shift: 0, cover: true },
    "Cave"     => { species: 4..6, max: 12, density: 5, shift: 1, cover: true },
    "Water"    => { species: 2..4, max: 8, density: 2, shift: 0, type: :WATER, cover: :surf },
    "OldRod"   => { species: 1..2, max: 2, shift: -6, type: :WATER, weak: true },
    "GoodRod"  => { species: 2..3, max: 3, shift: -3, type: :WATER },
    "SuperRod" => { species: 2..4, max: 4, shift: 2, type: :WATER }
  }.freeze

  # Wild levels. Cap of n seals = LevelCap's cap (the level of the next
  # lieutenant), else CAPS[n]. Places between two lieutenants climb from the
  # previous cap to LEVEL_REACH of the gap up to the next one; the first ones
  # start at START_LEVEL.
  START_LEVEL = 3
  CAPS = [14, 21, 24, 29, 43, 43, 47, 50, 63].freeze
  LEVEL_REACH = 0.8

  # A Pokémon that evolves by level shows up from that level on. One that
  # evolves another way (stone, friendship, trade...) shows up from that many
  # seals, by stage (2 = first evolution, 3 = second).
  STAGE_SEALS = { 2 => 3, 3 => 6 }.freeze

  # How often a Pokémon is drawn, by tier (« force » in the roster); « fort »
  # gains FORT_PER_SEAL per seal. Evolved stages are divided by their stage.
  TIER_WEIGHTS = { "faible" => 3.0, "moyen" => 2.0, "fort" => 0.5 }.freeze
  FORT_PER_SEAL = 0.25
  # Each table that already has a Pokémon makes it that much less likely
  # elsewhere, so that the whole roster shows up.
  REUSE_PENALTY = 0.7
end
